<?php
declare(strict_types=1);
require_once __DIR__ . '/../includes/bootstrap.php';require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/student_records.php';
$user=current_user();if(!$user||!in_array($user['role'],['Administrator','Head','Teacher','Clerk'],true)){http_response_code(403);exit('Access denied.');}
if($_SERVER['REQUEST_METHOD']!=='POST'||!verify_csrf()){http_response_code(419);exit('This form has expired. Refresh the page and try again.');}
$classId=filter_var($_POST['class_id']??null,FILTER_VALIDATE_INT);$date=(string)($_POST['attendance_date']??'');$entries=$_POST['attendance']??[];
if(!$classId||!valid_school_date($date)||!is_array($entries)||!$entries){$_SESSION['error']='Choose a class and date and mark each learner.';header('Location: ../?page=attendance');exit;}
$pdo=db();$classQuery=$pdo->prepare('SELECT id,form_level,stream,academic_year,class_teacher_id FROM class_groups WHERE id=:id');$classQuery->execute(['id'=>$classId]);$class=$classQuery->fetch();
if(!$class||($user['role']==='Teacher'&&(int)$class['class_teacher_id']!==(int)$user['id'])||(int)substr($date,0,4)!==(int)$class['academic_year']){http_response_code(403);exit('You cannot record attendance for this class and date.');}
$rosterQuery=$pdo->prepare("SELECT DISTINCT s.id FROM students s JOIN student_enrolments e ON e.student_id=s.id WHERE e.academic_year=:year AND e.form_level=:form AND COALESCE(e.stream,'')=:stream AND e.start_date<=:date_start AND (e.end_date IS NULL OR e.end_date>=:date_end)");$rosterQuery->execute(['year'=>$class['academic_year'],'form'=>$class['form_level'],'stream'=>$class['stream'],'date_start'=>$date,'date_end'=>$date]);$validIds=array_map('intval',$rosterQuery->fetchAll(PDO::FETCH_COLUMN));
if(!$validIds){$_SESSION['error']='There were no learners enrolled in this class on that date.';header('Location: ../?page=attendance&class_id='.$classId.'&date='.rawurlencode($date));exit;}
$validStatuses=['Present','Absent','Late','Excused'];$records=[];$counts=array_fill_keys($validStatuses,0);
foreach($validIds as $studentId){$entry=$entries[$studentId]??null;if(!is_array($entry)||!in_array($entry['status']??'',$validStatuses,true)){$_SESSION['error']='Select a status for every learner before saving the register.';header('Location: ../?page=attendance&class_id='.$classId.'&date='.rawurlencode($date));exit;}$note=trim((string)($entry['note']??''));if(strlen($note)>255){$_SESSION['error']='Attendance notes must be 255 characters or fewer.';header('Location: ../?page=attendance&class_id='.$classId.'&date='.rawurlencode($date));exit;}$records[]=[$studentId,$entry['status'],$note];$counts[$entry['status']]++;}
if(count($entries)!==count($validIds)){$_SESSION['error']='The register changed while it was open. Reload and mark all current learners.';header('Location: ../?page=attendance&class_id='.$classId.'&date='.rawurlencode($date));exit;}
try{$pdo->beginTransaction();$upsert=$pdo->prepare("INSERT INTO attendance (student_id,attendance_date,status,note,recorded_by) VALUES (:student,:date,:status,:note,:user) ON DUPLICATE KEY UPDATE status=VALUES(status),note=VALUES(note),recorded_by=VALUES(recorded_by),recorded_at=CURRENT_TIMESTAMP");foreach($records as [$studentId,$status,$note])$upsert->execute(['student'=>$studentId,'date'=>$date,'status'=>$status,'note'=>$note?:null,'user'=>$user['id']]);audit_log('attendance.register_saved','attendance',null,['class_id'=>$classId,'date'=>$date,'counts'=>$counts]);$pdo->commit();$_SESSION['notice']='Attendance saved for '.count($records).' learners.';}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();error_log('Attendance save failed: '.$e->getMessage());$_SESSION['error']='Attendance could not be saved. Please try again.';}
header('Location: ../?page=attendance&class_id='.$classId.'&date='.rawurlencode($date));exit;
